BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-11499'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='8Z3208' OR source_url ~ '[?&]id=11499(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='b9003208-a6ee-4ef4-a19e-678963011499' OR slug='sam-na-kluea-pattani-factory-8z3208' OR (abs(latitude-6.881883)<0.0001 AND abs(longitude-101.260385)<0.0001 AND abs(land_area_sqm-34407.6)<1)) THEN RAISE NOTICE 'SAM 8Z3208 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('b9003208-a6ee-4ef4-a19e-678963011499', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'factory', 'business', 'sale', 'whole_property', 'โรงงานและโกดังถนนนาเกลือ ปัตตานี 21 ไร่ 2 งาน 1.9 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดินพร้อมโรงงาน โกดัง ห้องเย็นและสิ่งปลูกสร้าง ถนนนาเกลือ ตำบลบานา อำเภอเมืองปัตตานี จังหวัดปัตตานี รวม 13 โฉนด เนื้อที่ 21 ไร่ 2 งาน 1.9 ตร.ว. หรือ 8,601.9 ตร.ว. (34,407.6 ตร.ม.) ราคาประกาศขายทั้งทรัพย์ 96,597,000 บาท รหัส SAM 8Z3208

ที่ดินสองกลุ่มและการเข้าถึง

กลุ่มที่ 1 มี 12 แปลงติดต่อกัน โฉนดเลขที่ 1929, 4155, 9924, 9925, 9926, 9927, 10783, 10784, 10785, 10786, 10787 และ 11308 เนื้อที่ 13 ไร่ 38.2 ตร.ว. แปลงรวมรูปหลายเหลี่ยม ด้านตะวันออกติดถนนกว้างประมาณ 102 เมตร ลึกสุดประมาณ 221 เมตร ด้านตะวันตกติดคลองปูลาประมาณ 42 เมตร

กลุ่มที่ 2 มีโฉนดเลขที่ 9469 จำนวน 1 แปลง เนื้อที่ 8 ไร่ 1 งาน 63.7 ตร.ว. ด้านตะวันออกติดคลองปูลาประมาณ 160 เมตร ลึกสุดประมาณ 90 เมตร ด้านตะวันตกติดแม่น้ำปัตตานีประมาณ 215 เมตร ไม่มีด้านใดติดทางสาธารณประโยชน์

สองกลุ่มมีคลองปูลาคั่น ไม่ใช่ที่ดินผืนเดียวติดต่อกัน SAM ระบุว่าต้องใช้สะพานคอนกรีตข้ามคลองเพื่อเข้ากลุ่มที่ 2 และให้ตรวจสิทธิใช้ทางก่อนเสนอซื้อ ควรตรวจเจ้าของสะพาน สิทธิทางผ่าน ภาระจำยอม สภาพและความสามารถรับน้ำหนัก ไม่รับรองว่ารถบรรทุกเข้าได้หรือมีสิทธิจดทะเบียนแล้ว ถนนนาเกลือหน้ากลุ่มที่ 1 เป็นทางสาธารณประโยชน์ ผิวลาดยางประมาณ 12 เมตร เขตทางประมาณ 20 เมตร ตามต้นทาง

สิ่งปลูกสร้างและขอบเขตการโอน

SAM ระบุทะเบียนรับโอน 23 รายการ ได้แก่ ป้อมยาม โกดัง 2 รายการ อาคารรับสินค้า สำนักงาน 2 ชั้น ห้องเครื่อง 2 ชั้น ร้านค้า 3 ชั้น โรงกลึง อาคารคลุมเครื่องกำเนิดไอน้ำ ห้องน้ำพนักงาน ห้องเย็น ห้องเครื่อง โรงน้ำแข็ง แผนกปลาสด สำนักงานและห้องเย็น อาคารตรวจสอบคุณภาพ 2 ชั้น บ้านพักคนงาน แผนกบุคคล 2 ชั้น แผนกวัตถุดิบ คสล. แผนกปลาแห้งและร้านค้า โรงอาหาร อาคารเก็บอุปกรณ์ตากปลา และแผนกปลากรอบ

ผลสำรวจระบุ 25 รายการ ลักษณะต่างจากทะเบียนบางส่วน รวมป้อมยาม โรงอาหาร ห้องน้ำ แผนกปลาแห้งและร้านค้า แผนกปลาสด แผนกปลากรอบ อาคารตรวจสอบคุณภาพ 2 ชั้น แผนกวัตถุดิบ แผนกบุคคล 2 ชั้น ห้องเย็นชั้นเดียว สำนักงาน 2 ชั้นพร้อมชั้นลอย ห้องเครื่องชั้นเดียว โรงน้ำแข็ง อาคารพักอาศัย 2 ชั้นและส่วนซ่อมบำรุง โกดังชั้นเดียว ห้องเย็น 2 ชั้น อาคารรับสินค้า อาคารพักอาศัย 2 ชั้น ห้องเครื่อง 2 ชั้น ร้านค้า 3 ชั้นพร้อมส่วนโล่งหลังคาคลุม โรงกลึงและที่พักอาศัย 2 ชั้น คานเรือ บ้านพักคนงานชั้นเดียว บ่อตกตะกอน และบ่อบำบัดน้ำเสีย

ต้นทางระบุโรงอาหาร คานเรือ บ่อตกตะกอนและบ่อบำบัดน้ำเสียมีสภาพทรุดโทรม และยืนยันว่าโอนให้ผู้ซื้อได้เฉพาะรายการที่ SAM จดทะเบียนรับโอนกรรมสิทธิ์เท่านั้น ต้องเทียบรายการทะเบียนกับผังขยายและอาคารจริง ไม่ถือว่าสิ่งปลูกสร้างหรือเครื่องจักรทุกชิ้นที่สำรวจพบรวมในการขายโดยอัตโนมัติ

ทำเลและข้อควรตรวจสอบ

ตั้งอยู่ในย่านที่อยู่อาศัยและเกษตรกรรม ใกล้มัสยิดยูโย สถานีอนามัยบานาและโรงเรียนชุมชนบ้านยูโย ตาม SAM จากถนนนาเกลือฝั่งยะรังมุ่งหน้าสะพานปลา ผ่านถนนรามโกมุทและโรงเรียนเมืองปัตตานี ทรัพย์อยู่ซ้ายมือระหว่างซอยนาเกลือ 21 และ 23 ก่อนถึงถนนเกษมสำราญประมาณ 920 เมตร

SAM ระบุสีผังเมืองเป็นสีส้ม ควรตรวจประเภทกิจการที่อนุญาต ใบอนุญาตโรงงาน ระบบห้องเย็น โรงน้ำแข็ง ระบบบำบัดและข้อกำหนดริมคลอง/แม่น้ำปัจจุบัน ต้นทางไม่ยืนยันสถานะเดินเครื่อง กำลังผลิต รายได้ ผู้เช่า เครื่องจักรที่รวมขายหรือพื้นที่ใช้สอยรวม จึงไม่เสนอเป็นโรงงานพร้อมผลิต

ภาพและการติดต่อ

ภาพจริงและผังจาก SAM รวม 13 ภาพ ใช้ผังขยายแปลงและสิ่งปลูกสร้างจากเอกสารแนบ ภาพถ่ายลงวันที่ 20 กรกฎาคม 2567 ควรตรวจสภาพปัจจุบัน พิกัด 6.881883, 101.260385 ดึงจากลิงก์นำทาง SAM และตรงกับแผนที่ เป็นจุดอ้างอิงรวม ไม่ใช่แนวเขตรังวัดของแต่ละกลุ่ม

ตรวจราคาและสถานะซื้อตรงวันที่ 15 กันยายน 2569 ติดต่อ SAM โทร.02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 8Z3208 เพื่อยืนยันราคา เอกสาร สิทธิข้ามคลอง รายการโอนและเงื่อนไขล่าสุด', 96597000, false, 34407.6, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ถนนนาเกลือ ระหว่างซอย21และ23', 'ที่ดินสองกลุ่ม มีคลองปูลาคั่น', 'ถนนนาเกลือ', 6.881883, 101.260385, 'ปัตตานี', 'เมืองปัตตานี', 'บานา', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-na-kluea-pattani-factory-8z3208') RETURNING id INTO property_listing_id;
