INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=11499&keyref=', '8Z3208', now(), 'Checked2026-09-15. THB96597000,34407.6sqm,13Chanote plots/2canal-separated groups. Group2title9469 no public frontage; concrete bridge access rights require verification.23registered versus25surveyed;registered transfer only. Dilapidated canteen/slipway/treatment ponds disclosed; current operations/machinery unconfirmed.13authentic images/plans including expanded attachments;photo date2024-07-20. Navigation/map agree. All-status source/code/page/deed/nearby duplicate search empty.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Na Kluea Road Factory and Warehouses, Pattani — 21 Rai', 'Factory, warehouses, cold stores and associated structures on Na Kluea Road, Bana, Mueang Pattani, Pattani.13Chanote titles total21rai2ngan1.9sq.wah,or8601.9sq.wah(34407.6sq.m.). SAM whole-property asking price THB96,597,000,reference8Z3208.

Two non-contiguous groups separated by Khlong Pu La. Group1:12adjoining titles1929,4155,9924–9927,10783–10787,11308,total13rai38.2sq.wah. Approximately102m eastern road frontage,221m maximum depth and42m western canal boundary. Group2:single title9469,8rai1ngan63.7sq.wah,approximately160m eastern canal boundary,90m maximum depth and215m western frontage on Pattani River. Group2 has no public-road frontage.

SAM says access to group2 requires a concrete bridge over the canal and expressly calls for access-right verification. Check bridge ownership,rights/easements,condition and load capacity; truck access or registered rights are not certified. Public Na Kluea Road serves group1,approximately12m paved carriageway and20m right of way according to source.

Registered inventory23entries includes guardhouse,two warehouses,receiving building,2-storey office,2-storey plant room,3-storey shop,lathe workshop,steam-generator shelter,staff toilets,cold store,plant room,ice plant,fresh-fish section,office/cold store,2-storey quality-control building,workers housing,2-storey personnel section,raw-material building,dried-fish/shop section,canteen,fish-drying equipment store and crispy-fish section.

Survey instead lists25entries including varied cold-store/office/plant/residential buildings,a slipway,sedimentation pond and wastewater treatment pond. SAM describes canteen,slipway,sedimentation and wastewater ponds as dilapidated. Transfer is expressly limited to SAM registered acquisition inventory. Reconcile registered list,expanded plans and actual structures; surveyed items and machinery are not automatically included.

Source reports residential/agricultural surroundings near Yuyo Mosque,Bana health station and Ban Yuyo community school. From Yarang toward the fishing pier along Na Kluea Road,pass Ram Komut Road and Mueang Pattani school; property left between soi21and23,approximately920m before Kasem Samran Road.

Source zoning orange. Verify current permitted industrial use,factory licence,cold-store/ice-plant/treatment systems and canal/river requirements. Current operations,capacity,income,tenants,included machinery and usable area are unconfirmed. Not represented as production-ready.

